def extract_name(desc):
    # Take the part before " specializes"/" provides"/" is"/" harnesses"/" offers"
    m = re.search(r'^(.*?)(?:,\s*based\s+in\s+\w+,?)?\s+(?:specializes|provides|is\s|harnesses|offers|develops|manufactures|operates)', desc)
    if m:
        return m.group(1).strip().rstrip(',')
    return desc.split('.')[0]

